insert into public.qa_features (key, department, title, tracker_key, href, purpose, steps, expected, sort) values
  ('public-site', 'account', 'Public website, navigation and search', (select key from public.dev_tracker where key = 'public-site'), '/', 'The first impression: every page loads, menus work and search finds content.', array['Open the home page on your phone and on a computer.', 'Open each top menu (The Art of Self, Relationships, Professional, Journey, Counseling) and tap two links in each.', 'Search for "boundaries" and open a result.', 'Open the phone menu and close it.']::text[], 'Every page loads with images, no broken links, menus open and close smoothly, and search returns relevant results.', 0),
  ('membership-page', 'account', 'Memberships page', (select key from public.dev_tracker where key = 'payments'), '/membership', 'Members understand each membership and what''s included before joining.', array['Open Memberships.', 'Read each membership card: price, what''s included, Journey allowance.', 'Tap a Join button.']::text[], 'Prices and inclusions match what you approved; joining shows that enrollment opens soon (payments are off).', 10),
  ('free-registration', 'account', 'Begin free with one primary society', (select key from public.dev_tracker where key = 'free-registration'), '/join/free', 'A new member can create a free account and choose one society, with age rules enforced.', array['Open Join free (use View as or a test account; public registration stays closed).', 'Choose each society and read the age requirement: Business 21+, Singles 30+, Couples 21+.', 'Try a birth date under the required age.']::text[], 'The form explains each society; underage choices are refused politely; public sign-up stays closed until you open it.', 20),
  ('sign-in', 'account', 'Sign in, password reset and two-step verification', (select key from public.dev_tracker where key = 'owner-tools'), '/sign-in', 'Members and staff can sign in securely and recover access.', array['Sign out, then sign in again.', 'Open Forgot password and request a reset (use your own email).', 'Confirm the two-step verification code prompt for the Owner Portal.']::text[], 'Sign-in works, the reset email arrives, and the Owner Portal always asks for your verification code.', 30),
  ('dashboard', 'account', 'Personalized member dashboard', (select key from public.dev_tracker where key = 'dashboard'), '/app', 'Each member sees only their own societies, progress and Journey allowance.', array['Open My dashboard.', 'Use the gold View as bar to switch between each membership type.', 'Check which spaces and quick links appear for each.']::text[], 'Each membership sees only its own spaces, plus Explore Memberships; nothing from other societies appears.', 40),
  ('society-transitions', 'account', 'Society transitions (e.g., Singles to Couples)', (select key from public.dev_tracker where key = 'society-transitions'), '/app/membership', 'A member can change their primary society without losing their Art of Self history.', array['Open Membership & billing.', 'Find the society section and review the transition options and eligibility notes.']::text[], 'Eligible transitions are offered with clear explanations; ineligible ones explain why; history is preserved.', 50),
  ('legal-center', 'account', 'Legal center and agreements', (select key from public.dev_tracker where key = 'legal-journey'), '/legal', 'Policies are readable and members are asked to accept new versions.', array['Open Legal & policies and open three documents.', 'Check that drafts awaiting attorney review are not presented as final.']::text[], 'Documents are readable on phone and computer; draft status is clear.', 60),
  ('art-of-self-home', 'art-of-self', 'The Art of Knowing Yourself (home)', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself', 'The hub for self-discovery: progress, modules and curricula.', array['Open The Art of Self.', 'Check your progress ring and the list of modules.', 'Open the first module, then come back.']::text[], 'Progress is accurate, every module opens, banners show the whole image.', 70),
  ('who-am-i', 'art-of-self', 'Who Am I? modules', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself/who-am-i/beyond-my-titles', 'Ten self-discovery modules, completed independently or with Journey.', array['Open Beyond my titles.', 'Choose Continue Independently, answer two questions and Save privately.', 'Choose Chat With Journey, answer one question, then Review and save my answers.', 'Correct one answer before saving.']::text[], 'Answers save; Journey asks one question at a time, builds on your answers, and nothing saves until you confirm.', 80),
  ('identity-curriculum', 'art-of-self', 'Identity & Self-Love curriculum', (select key from public.dev_tracker where key = 'identity-curriculum'), '/app/know-yourself/identity-self-love', 'Six founding lessons with guided answers and a personal analysis.', array['Open lesson 1, answer each question and read the guidance under your choice.', 'Save, then open the Personal Discovery card at the bottom.', 'Review the drafted answer wording for accuracy to your philosophy.']::text[], 'Guidance appears for each choice, the analysis has no scores or labels, and the wording reflects your philosophy.', 90),
  ('ei-curriculum', 'art-of-self', 'Emotional Intelligence curriculum and areas', (select key from public.dev_tracker where key = 'ei-curriculum'), '/app/know-yourself/emotional-intelligence/lessons', 'Six lessons, five EI areas with scenarios, and a private EI profile.', array['Complete one lesson.', 'Open an EI area page from Emotional Intelligence and try its scenario.', 'Fill in two lines of your EI profile and save.']::text[], 'Scenarios respond to your choice; reflections save privately; no diagnosis or labels.', 100),
  ('boundaries', 'art-of-self', 'Boundaries & non-negotiables', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself/boundaries', 'Four areas for values, will-do, won''t-do and how to say it.', array['Complete one area and save.', 'Check that "My standards" shows your words.']::text[], 'Your standards appear exactly as written; nothing is shared with anyone.', 110),
  ('love-languages', 'art-of-self', 'Love Language profile', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself/love-languages', 'Discover and rank how you give and receive love, with private sharing controls.', array['Answer the ten either/or moments.', 'Adjust the ranking and save.', 'Review the sharing switches (partner, matches, Journey).']::text[], 'Rankings save, sharing is off unless you turn it on, and the page never calls love languages a fixed type.', 120),
  ('portfolio', 'art-of-self', 'Personal Discovery Portfolio', (select key from public.dev_tracker where key = 'portfolio'), '/app/know-yourself/portfolio', 'Everything discovered, together, with dated versions, corrections and print.', array['Open the Portfolio.', 'Add a correction to one section.', 'Use Print.']::text[], 'Sections reflect your saved answers, corrections appear, printing looks clean, and free members see no AI content.', 130),
  ('growth', 'art-of-self', 'Growth goals and history', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself/growth', 'Personal goals and how your answers have grown over time.', array['Add a goal, mark it achieved, then delete it.', 'Review "How you''ve grown" history.']::text[], 'Goals update instantly; history shows earlier answers with dates.', 140),
  ('journey-activation', 'journey', 'Activate & test Journey (owner)', (select key from public.dev_tracker where key = 'intelligence-center'), '/admin/journey', 'One place to activate, test and switch off Journey privately.', array['Check every status tile.', 'Write to Journey in the test panel.', 'Switch to Talk to Journey and speak for a minute.']::text[], 'Status tiles are accurate; both conversations work and use only your testing budget.', 150),
  ('journey-text', 'journey', 'Written conversations', (select key from public.dev_tracker where key = 'journey-text'), '/app/journey', 'Journey''s written conversations, from the member''s side.', array['Start a new conversation about something real to you.', 'Reply three times.', 'Check her replies build on what you said and never repeat her introduction.']::text[], 'Warm, intelligent replies grounded in your philosophy; one question at a time; continuity throughout.', 160),
  ('journey-voice', 'journey', 'Live voice (GPT-Live)', (select key from public.dev_tracker where key = 'journey-voice'), '/app/journey/voice', 'Natural spoken conversation with interruption handling.', array['Start a live conversation on your phone.', 'Interrupt her once mid-sentence.', 'End the conversation and check the transcript shows both of you.']::text[], 'Natural rhythm, no looping or stuttering, she stops when interrupted, and minutes are counted correctly.', 170),
  ('journey-intelligence', 'journey', 'Journey''s intelligence and personality', (select key from public.dev_tracker where key = 'journey-intelligence'), '/admin/journey/quality', 'Journey teaches from your Blueprint and philosophy, not as a generic assistant.', array['Run all nine quality tests.', 'Read each conversation against the six criteria.', 'Note anything that doesn''t sound like Journey.']::text[], 'Every conversation listens, builds on answers, teaches, and sounds like Journey.', 180),
  ('universal-journey', 'journey', 'Journey in every lesson and the Ask Journey button', (select key from public.dev_tracker where key = 'universal-journey'), '/app/know-yourself/who-am-i/beyond-my-titles', 'Talk, Chat or Continue Independently on every module; Ask Journey on every page.', array['Use Chat With Journey on a lesson and save reviewed answers.', 'Tap Ask Journey on two different pages and ask about the page.']::text[], 'Journey knows which lesson or page you''re on; your page stays as you left it.', 190),
  ('discovery-sessions', 'journey', 'Adaptive Discovery Sessions', (select key from public.dev_tracker where key = 'discovery-sessions'), '/app/journey/discover', 'Journey asks adaptive questions and writes a category summary.', array['Begin a session in one category.', 'Answer five questions.', 'Ask for the summary.']::text[], 'Questions adapt to your answers; the summary uses the expected headings with no labels or scores.', 200),
  ('journey-analyses', 'journey', 'Journey-written analyses', (select key from public.dev_tracker where key = 'journey-analyses'), '/app/know-yourself/identity-self-love', 'Journey writes a personal analysis from a member''s own answers, with consent.', array['At the end of a curriculum, request Journey''s analysis and confirm consent.', 'Read it against the self-guided version.']::text[], 'Grounded in your answers, uses the curriculum headings, no scores or diagnoses.', 210),
  ('customize-journey', 'journey', 'Customize Your Journey', (select key from public.dev_tracker where key = 'customize-journey'), '/app/journey/customize', 'Avatar, voice, language, regional style, age style, communication style and pace.', array['Filter avatars by age appearance and choose one.', 'Choose a masculine voice, then a feminine voice, and play previews.', 'Set a language other than English, save, and talk to Journey.']::text[], 'Choices save; previews play; Journey converses in your chosen language with the same philosophy.', 220),
  ('voice-studio', 'journey', 'Voice model comparison', (select key from public.dev_tracker where key = 'voice-studio'), '/admin/journey', 'Compare GPT-Live and Realtime models with real expenses.', array['In the voice tab, test two models with the same scenario.', 'Compare the actual expense table.']::text[], 'Both models connect; actual expenses are recorded per model.', 230),
  ('training-review', 'journey', 'Blueprint and training review', (select key from public.dev_tracker where key = 'training-library'), '/admin/journey/review', 'Review and approve the Blueprint and the 28 training entries.', array['Read the Blueprint.', 'Open one category, edit an entry, approve the category.']::text[], 'Edits save; approving a category marks its entries approved; members only see approved content.', 240),
  ('journey-sessions', 'journey', 'Private Sessions', (select key from public.dev_tracker where key = 'session-billing'), '/app/journey/sessions', 'Paid private sessions with quotes, notices and pause rules.', array['Open Private Sessions (members see Coming soon).', 'Review the session options and descriptions.']::text[], 'Prices stay hidden until you publish them; nothing can be purchased while payments are off.', 250),
  ('daily-journey', 'journey', 'Daily Journey, check-ins and manifestations', (select key from public.dev_tracker where key = 'daily'), '/app/journey/check-ins', 'Daily intentions, manifestations and gentle check-ins on the member''s terms.', array['Open check-ins and review today''s intention.', 'Change notification preferences.']::text[], 'Preferences save; nothing personal appears in notifications without permission.', 260),
  ('journey-memory', 'journey', 'What Journey remembers', (select key from public.dev_tracker where key = 'memory'), '/app/journey/memory', 'Members control what Journey remembers.', array['Open the page, add a memory, then delete it.', 'Turn memory off.']::text[], 'Memories are added and removed instantly; turning memory off stops Journey from using them.', 270),
  ('business-explore', 'professional', 'The Professional Society (public)', (select key from public.dev_tracker where key = 'professional-society'), '/business', 'The public introduction and Explore before you join.', array['Open The Professional Society and Explore.', 'Check age (21+) and membership information.']::text[], 'Clear, premium presentation; joining explains that enrollment opens soon.', 280),
  ('business-onboarding', 'professional', 'Business onboarding', (select key from public.dev_tracker where key = 'professional-society'), '/app/business/onboarding', 'New business members set up their profile and interests.', array['View as a Professional Society member.', 'Complete onboarding with fictional business details.']::text[], 'Each step saves; the dashboard reflects the details afterwards.', 290),
  ('business-board', 'professional', 'Business Connection Board', (select key from public.dev_tracker where key = 'professional-society'), '/app/business/board', 'Members post and respond to business opportunities.', array['Create a post with fictional details.', 'Open another post and respond.', 'Report a post.']::text[], 'Posts appear, responses go to the private inbox, reports reach moderation.', 300),
  ('business-inbox', 'professional', 'Private business inbox', (select key from public.dev_tracker where key = 'professional-society'), '/app/business/inbox', 'Private one-to-one business messages.', array['Open a conversation and send a message.', 'Check it from the other test account.']::text[], 'Messages arrive only to the two participants; blocking stops further messages.', 310),
  ('webinars', 'professional', 'The Knowledge Exchange (webinars)', (select key from public.dev_tracker where key = 'professional-society'), '/webinars', 'Members browse, register for and host webinars.', array['Open a webinar and register.', 'Host a webinar with a fictional title and image.']::text[], 'Registration confirms; hosted webinars go to review before appearing publicly.', 320),
  ('singles-onboarding', 'singles', 'Four-stage Personal Society onboarding', (select key from public.dev_tracker where key = 'onboarding'), '/app/relationships/onboarding', 'Singles move through four intentional stages before connecting.', array['View as a Singles member.', 'Complete stage 1 and open stage 2.']::text[], 'Each stage saves and unlocks in order; age 30+ is enforced.', 330),
  ('readiness', 'singles', 'Relationship Readiness Profile', (select key from public.dev_tracker where key = 'readiness'), '/app/readiness', 'Readiness reflection without labels or unsupported scores.', array['Answer the readiness questions.', 'Read the results.']::text[], 'Reflections only; no diagnosis or compatibility verdicts. Personal scoring stays off until professionally reviewed.', 340),
  ('love-languages-together', 'singles', 'Love languages for dating', (select key from public.dev_tracker where key = 'personal-society'), '/app/relationships/love-languages', 'Members see love languages in a dating context, with sharing only by consent.', array['Open Love languages together.', 'Check what a match would see with sharing off.']::text[], 'Nothing is shared without consent; love languages are never presented as a compatibility score.', 350),
  ('matchmaking', 'singles', 'Matchmaking and introductions', (select key from public.dev_tracker where key = 'matchmaking'), '/app/relationships', 'Introductions between eligible singles (not yet built).', array['Open Singles & couples home and confirm matchmaking shows as coming soon.']::text[], 'Clearly marked as coming soon; no unfinished matching is exposed.', 360),
  ('couples-home', 'couples', 'Couples home and love languages together', (select key from public.dev_tracker where key = 'personal-society'), '/app/relationships', 'Couples see shared tools and each other''s shared love languages.', array['View as a Couples member.', 'Open Love languages together.']::text[], 'Only what each partner chose to share is visible.', 370),
  ('couples-calendar', 'couples', 'Couples calendar', (select key from public.dev_tracker where key = 'couples-moments'), '/app/relationships/calendar', 'A private shared calendar for two.', array['Add an event.', 'Check it from the partner test account.']::text[], 'Events are visible only to the two partners.', 380),
  ('exclusive', 'couples', 'The Exclusive Connection', (select key from public.dev_tracker where key = 'exclusive'), '/app/relationships/exclusive', 'Two members agree to an exclusive connection.', array['Send a request from one test account and accept it from the other.', 'End it.']::text[], 'Both members see the change; ending it notifies kindly without sharing private details.', 390),
  ('wellness-center', 'counseling', 'Counseling & Wellness Center', (select key from public.dev_tracker where key = 'wellness-center'), '/app/wellness', 'Open to every member: Journey support, independent professionals, The Art of Wellness.', array['Open the center as a free member and as a paid member (View as).', 'Save support preferences.']::text[], 'Preferences save privately; Journey is offered only to paid members; clinical services show Coming soon.', 400),
  ('crisis-resources', 'counseling', 'Crisis resources', (select key from public.dev_tracker where key = 'crisis-page'), '/wellness', 'Always available, with no account or payment.', array['Sign out and open the crisis page.', 'Check 988 and 911 information.']::text[], 'Loads without an account; information is accurate and easy to find.', 410),
  ('art-of-wellness', 'counseling', 'The Art of Wellness (in-house)', (select key from public.dev_tracker where key = 'art-of-wellness'), '/app/wellness/art-of-wellness', 'In-house counseling presented as Coming Soon.', array['Open the page and read it.']::text[], 'Clearly Coming Soon; no bookings or clinical services are possible.', 420),
  ('professionals-apply', 'counseling', 'Professional applications', (select key from public.dev_tracker where key = 'counselor-portal'), '/professionals/apply', 'Counselors, coaches and mentors apply to join.', array['Open the application and review required credentials.']::text[], 'Applications stay closed until you open them; credentials and 21+ are required.', 430),
  ('becoming-journal', 'counseling', 'The Art of Becoming and private journal', (select key from public.dev_tracker where key = 'journal'), '/app/counseling/journal', 'Premium personal development with a private journal.', array['View as an Art of Becoming member.', 'Write and save a journal entry.']::text[], 'The entry saves and is visible only to the member.', 440),
  ('journey-allowance', 'financial', 'Journey allowance and message packages', (select key from public.dev_tracker where key = 'journey-plus'), '/app/journey/plus', 'Members see their allowance and optional packages.', array['Open My Journey allowance as a paid member (View as).', 'Check remaining messages and minutes.']::text[], 'Accurate allowance; packages hidden or unpurchasable until you approve and payments are live.', 450),
  ('stripe-checkout', 'financial', 'Membership checkout (Stripe sandbox)', (select key from public.dev_tracker where key = 'payments'), '/membership', 'Checkout calculates correctly using Stripe''s test mode only.', array['When sandbox testing is enabled, complete a checkout with Stripe''s test card 4242 4242 4242 4242.', 'Confirm the membership activates.']::text[], 'Correct price and tax; membership activates; no real charge is ever made.', 460),
  ('revenue', 'financial', 'Revenue and AI expense reporting', (select key from public.dev_tracker where key = 'revenue-split'), '/admin/revenue', 'Revenue and AI costs are reported separately and accurately.', array['Open Revenue.', 'Compare AI expense with the Journey Intelligence Center.']::text[], 'Figures agree; Journey sessions, credits and counseling are separable.', 470),
  ('budgets', 'financial', 'AI budgets and safeguards', (select key from public.dev_tracker where key = 'financial-controls'), '/admin/journey', 'Company and owner testing budgets stop spending at the limits.', array['Check the testing budget and spent amount.', 'Confirm members can''t use Journey while payments are off.']::text[], 'Spending never exceeds the budgets; public access stays closed.', 480),
  ('owner-portal', 'admin', 'Owner Portal overview', (select key from public.dev_tracker where key = 'owner-tools'), '/admin', 'Every owner tool is reachable and loads.', array['Open the Owner Portal and visit each section in the menu.']::text[], 'Every section loads with accurate information; nothing shows another member''s private data.', 490),
  ('view-as', 'admin', 'View as (membership previews)', (select key from public.dev_tracker where key = 'owner-tools'), '/app', 'See the platform exactly as each membership does.', array['Switch through all seven personas.', 'Visit a Coming Soon page while viewing as a member.']::text[], 'Each persona sees its own spaces; Coming Soon pages open for you with a note.', 500),
  ('curriculum-studio', 'admin', 'Curriculum Studio', (select key from public.dev_tracker where key = 'owner-tools'), '/admin/curriculum', 'Edit and publish curriculum wording with versions.', array['Edit one guidance sentence and save a draft.', 'Compare versions.']::text[], 'Drafts save without changing what members see until published.', 510),
  ('development-tracker', 'admin', 'Development Tracker', (select key from public.dev_tracker where key = 'tracker'), '/admin/development', 'Honest status of every feature.', array['Filter by stage.', 'Record "I tested this" for one feature.']::text[], 'Stages are accurate; only you can record testing and approval.', 520),
  ('launch-controls', 'admin', 'Launch controls', (select key from public.dev_tracker where key = 'owner-tools'), '/admin/launch', 'Switches for registration, payments and societies.', array['Review every switch without changing it.']::text[], 'All public switches show Off until you decide to launch.', 530),
  ('privacy-safety', 'security', 'Privacy & safety settings', (select key from public.dev_tracker where key = 'trust-safety'), '/app/safety', 'Members control visibility, blocking and reporting.', array['Open Privacy & safety and review each control.', 'Block and unblock a test account.']::text[], 'Controls save; blocked accounts can''t contact or see the member.', 540),
  ('verification', 'security', 'Identity verification', (select key from public.dev_tracker where key = 'identity-verification'), '/app/verify', 'ID and photo verification (provider not yet connected).', array['Open Identity verification.']::text[], 'Clearly explains verification is coming; no personal documents are requested yet.', 550),
  ('private-data', 'security', 'Private reflections stay private', (select key from public.dev_tracker where key = 'art-of-self'), '/app/know-yourself', 'Reflections, journals and Journey conversations are never visible to others or staff.', array['Save a reflection with one test account.', 'Check that another test account and the Owner Portal can''t see it.']::text[], 'Only the member can see their reflections; owner reports show totals only.', 560),
  ('access-control', 'security', 'Owner Portal access and two-step verification', (select key from public.dev_tracker where key = 'owner-tools'), '/admin/security', 'Only authorized staff reach the Owner Portal, always with two-step verification.', array['Open Security.', 'Sign in from a new browser and confirm the verification code is required.']::text[], 'Unauthorized accounts are refused; your verification code is always required.', 570)
